'QZ_Tray_Printer' => 'QZ Tray (ម៉ាស៊ីនបោះពុម្ពនៅលើកុំព្យូទ័រនេះ)',
'QZ_Printer_Name_Hint' => 'ឈ្មោះម៉ាស៊ីនបោះពុម្ពដូចដែលបង្ហាញនៅលើកុំព្យូទ័រដែលកំពុងដំណើរការ QZ Tray។ ទុកឱ្យនៅទទេដើម្បីប្រើម៉ាស៊ីនបោះពុម្ពលំនាំដើមរបស់កុំព្យូទ័រនោះ។ ចុច ⟳ ដើម្បីរកមើលម៉ាស៊ីនបោះពុម្ព។',
'QZ_Not_Running' => 'QZ Tray មិនកំពុងដំណើរការនៅលើកុំព្យូទ័រនេះទេ។ ដំឡើងវាពី qz.io ហើយទុកឱ្យវាដំណើរការ បន្ទាប់មកអនុញ្ញាតគេហទំព័រនេះនៅពេល QZ សួរ។',
'Detect_Printers' => 'រកមើលម៉ាស៊ីនបោះពុម្ព',
'QZ_Download_Cert' => 'ទាញយកវិញ្ញាបនបត្រ (override.crt)',
'QZ_Setup_Title' => 'របៀបរៀបចំការបោះពុម្ព QZ Tray (ម្តងគត់ នៅលើកុំព្យូទ័រនីមួយៗដែលបោះពុម្ពស្លាក)',
'QZ_Step_Install' => '1. ដំឡើង QZ Tray នៅលើកុំព្យូទ័រនេះ — ទាញយកវាដោយឥតគិតថ្លៃពី qz.io បន្ទាប់មកចាប់ផ្តើមវា ហើយទុកឱ្យវាដំណើរការ (វាស្ថិតនៅក្នុង system tray លើ Windows ឬរបារម៉ឺនុយលើ macOS)។',
'QZ_Step_Connect' => '2. ភ្ជាប់ម៉ាស៊ីនបោះពុម្ពស្លាករបស់អ្នកតាម USB ហើយពិនិត្យថាវាត្រូវបានដំឡើងក្នុងប្រព័ន្ធប្រតិបត្តិការ (Windows: Settings > Printers & scanners — macOS: System Settings > Printers & Scanners)។',
'QZ_Step_Detect' => '3. ចុចប៊ូតុង ⟳ នៅជាប់ "ឈ្មោះម៉ាស៊ីនបោះពុម្ព" ខាងលើ ដើម្បីរកមើលម៉ាស៊ីនបោះពុម្ពនៅលើកុំព្យូទ័រនេះ បន្ទាប់មកជ្រើសរើសម៉ាស៊ីនបោះពុម្ពស្លាករបស់អ្នក។ ទុកវាលឱ្យនៅទទេដើម្បីប្រើម៉ាស៊ីនបោះពុម្ពលំនាំដើមរបស់កុំព្យូទ័រ។',
'QZ_Step_Cert' => '4. ដើម្បីបោះពុម្ពដោយគ្មានផ្ទាំងសុំការអនុញ្ញាត សូមទាញយកវិញ្ញាបនបត្រខាងក្រោម ហើយចម្លងវាទៅក្នុងថតដំឡើង QZ Tray ដោយប្តូរឈ្មោះទៅជា override.crt (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray)។ បន្ទាប់មកបិទ QZ Tray ហើយចាប់ផ្តើមវាម្តងទៀត។',
'QZ_Step_Test' => '5. ចុច "បោះពុម្ពស្លាកសាកល្បង" ខាងក្រោម។ ប្រសិនបើ QZ Tray សុំការអនុញ្ញាត សូមចុច Allow — នៅពេលដំឡើងវិញ្ញាបនបត្ររួច វានឹងមិនសួរម្តងទៀតទេ។',
'QZ_Step_Save' => '6. ចុច ដាក់ស្នើ ដើម្បីរក្សាទុកការកំណត់ទាំងនេះ។ ស្លាកពីទំព័របោះពុម្ពបាកូដ ឥឡូវនឹងបោះពុម្ពដោយផ្ទាល់នៅលើម៉ាស៊ីនបោះពុម្ពនេះ ដោយគ្មានប្រអប់បោះពុម្ពរបស់កម្មវិធីរុករក។',
'QZ_Setup_Note' => 'QZ Tray ដំណើរការនៅលើកុំព្យូទ័រដែលអ្នកកំពុងប្រើ ដូច្នេះវាដំណើរការសូម្បីតែនៅពេល Stocky ត្រូវបានបង្ហោះនៅលើម៉ាស៊ីនមេពីចម្ងាយ។ កុំព្យូទ័រនីមួយៗដែលបោះពុម្ពស្លាកត្រូវការដំឡើង QZ Tray។',

