'Cr_Guide_A_Test' => 'សោរបៀបសាកល្បងប្រើជាមួយ របៀបសាកល្បង ហើយសោផ្ទាល់ប្រើជាមួយ ផ្ទាល់ ពួកវាខុសគ្នា។ បើក កំណត់ហេតុក្រុមហ៊ុនដឹកជញ្ជូន ហើយអានចម្លើយរបស់ក្រុមហ៊ុនដឹកជញ្ជូន ដើម្បីដឹងមូលហេតុពិតប្រាកដ។',
'Cr_Guide_Q_City' => 'ក្រុមហ៊ុនដឹកជញ្ជូនបដិសេធទីក្រុង ឬអាសយដ្ឋាន',
'Cr_Guide_A_City' => 'ជ្រើសរើសទីក្រុងពីបញ្ជីទីក្រុងរបស់ក្រុមហ៊ុនដឹកជញ្ជូនក្នុងទម្រង់កក់ ក្រុមហ៊ុនដឹកជញ្ជូនទទួលយកតែឈ្មោះផ្ទាល់ខ្លួនរបស់ពួកគេប៉ុណ្ណោះ។ ក្រុមហ៊ុនដឹកជញ្ជូនដែលធ្វើការជាមួយអាសយដ្ឋានប្រៃសណីយ៍ ក៏ត្រូវការរដ្ឋ លេខកូដប្រៃសណីយ៍ និងលេខកូដប្រទេសពីរអក្សរផងដែរ។',
'Cr_Guide_Q_Webhook' => 'ស្ថានភាពមិនផ្លាស់ប្តូរដោយខ្លួនឯង',
'Cr_Guide_A_Webhook' => 'សម្រាប់ក្រុមហ៊ុនដឹកជញ្ជូនដែលបញ្ជូនបច្ចុប្បន្នភាព សូមពិនិត្យថា Webhook URL ត្រូវបានចុះឈ្មោះនៅក្រុមហ៊ុនដឹកជញ្ជូន៖ កំណត់ហេតុក្រុមហ៊ុនដឹកជញ្ជូន បង្ហាញរាល់បច្ចុប្បន្នភាពដែលបានទទួល ឬមូលហេតុដែលវាត្រូវបានបដិសេធ (ឧទាហរណ៍ សម្ងាត់ខុស)។ ក្រុមហ៊ុនដឹកជញ្ជូនផ្សេងទៀតត្រូវបានពិនិត្យតាមកាលវិភាគក្នុងការកំណត់ក្រុមហ៊ុនដឹកជញ្ជូន ហើយ ពិនិត្យស្ថានភាពឥឡូវនេះ សួរភ្លាមៗ។',
'Cr_Guide_Q_Stuck' => 'ការដឹកជញ្ជូនទំនិញបង្ហាញកំហុសពិនិត្យស្ថានភាព',
'Cr_Guide_A_Stuck' => 'ក្រុមហ៊ុនដឹកជញ្ជូនបានបដិសេធការពិនិត្យចុងក្រោយ មូលហេតុមាននៅលើការដឹកជញ្ជូនទំនិញ និងក្នុងកំណត់ហេតុក្រុមហ៊ុនដឹកជញ្ជូន។ បន្ទាប់ពីបរាជ័យម្តងហើយម្តងទៀត ការដឹកជញ្ជូនទំនិញលែងត្រូវបានពិនិត្យដោយស្វ័យប្រវត្តិទៀតហើយ៖ ដោះស្រាយមូលហេតុ បន្ទាប់មកប្រើ ពិនិត្យស្ថានភាពឥឡូវនេះ។',
'Cr_Guide_Q_Label' => 'គ្មានអ្វីបើកឡើងនៅពេលបោះពុម្ពស្លាក',
'Cr_Guide_A_Label' => 'កម្មវិធីរុករករបស់អ្នកបានរារាំងផ្ទាំងលេចឡើង។ អនុញ្ញាតផ្ទាំងលេចឡើងសម្រាប់គេហទំព័រនេះ ហើយព្យាយាមម្តងទៀត។',
