'Tfa_Guide_Codes_Text' => 'ភ្លាមៗបន្ទាប់ពីការរៀបចំ លេខកូដសង្គ្រោះ 8 ត្រូវបានបង្ហាញតែម្តង។ លេខកូដនីមួយៗជំនួសលេខកូដទូរសព្ទបានតែម្តង — សម្រាប់ទូរសព្ទដែលបាត់ ខូច ឬត្រូវបានកំណត់ឡើងវិញ។ ទាញយក ឬចម្លងពួកវា ហើយរក្សាទុកនៅកន្លែងដែលមានសុវត្ថិភាព ឆ្ងាយពីទូរសព្ទ។',
'Tfa_Guide_Codes_Note' => 'ជិតអស់ហើយឬ? "លេខកូដសង្គ្រោះថ្មី" នៅលើប្រវត្តិរូបជំនួសសំណុំទាំងមូល; លេខកូដចាស់លែងដំណើរការ។',
'Tfa_Guide_Signin_Title' => 'ការចូល',
'Tfa_Guide_Signin_Text' => 'បន្ទាប់ពីអ៊ីមែល និងពាក្យសម្ងាត់ ទំព័រចូលនឹងសួររកលេខកូដបច្ចុប្បន្នពីកម្មវិធី។ លេខកូដផ្លាស់ប្តូររៀងរាល់ 30 វិនាទី ហើយលេខកូដនីមួយៗប្រើបានតែម្តង។',
'Tfa_Guide_Signin_Trust' => 'ការធីក "កុំសួរម្តងទៀតនៅលើឧបករណ៍នេះ" នឹងរំលងលេខកូដនៅលើកម្មវិធីរុករកនោះរយៈពេល :days ថ្ងៃ។',
'Tfa_Guide_Signin_Recovery' => 'មិនមានទូរសព្ទនៅនឹងដៃឬ? ចុច "ប្រើលេខកូដសង្គ្រោះ" ហើយវាយបញ្ចូលលេខកូដមួយដែលបានរក្សាទុក។',
'Tfa_Guide_Admin_Title' => 'សម្រាប់អ្នកគ្រប់គ្រង',
'Tfa_Guide_Require_Title' => 'ធ្វើឱ្យវាជាកាតព្វកិច្ច',
'Tfa_Guide_Require_Text' => 'បើក "តម្រូវឱ្យមានការផ្ទៀងផ្ទាត់ពីរកត្តា" នៅលើកាតនេះ បន្ទាប់មកជ្រើសរើសតួនាទីដែលត្រូវប្រើវា — ឬទុកបញ្ជីឱ្យនៅទទេសម្រាប់អ្នកប្រើប្រាស់គ្រប់រូប។ ចុច ដាក់ស្នើ ដើម្បីរក្សាទុក។',
'Tfa_Guide_Require_Next' => 'គ្មាននរណាម្នាក់ត្រូវបានចាកចេញទេ។ អ្នកប្រើប្រាស់ដែលមិនទាន់មាន 2FA នឹងត្រូវបានណែនាំឱ្យរៀបចំនៅលើទំព័រចូលនៅពេលចូលលើកក្រោយ មុនពេលពួកគេចូលបាន ហើយនឹងឃើញលេខកូដសង្គ្រោះរបស់ពួកគេនៅទីនោះ។',
'Tfa_Guide_Require_Note' => 'អ្នកប្រើប្រាស់ដែលត្រូវបានតម្រូវ មិនអាចបិទវាពីប្រវត្តិរូបរបស់ពួកគេបានទេ។',
'Tfa_Guide_Trust_Title' => 'ឧបករណ៍ដែលទុកចិត្ត',
'Tfa_Guide_Trust_Text' => '"ចងចាំឧបករណ៍ដែលទុកចិត្ត" កំណត់រយៈពេលដែលកម្មវិធីរុករកអាចរំលងលេខកូដ បន្ទាប់ពីការចូលដោយជោគជ័យ។ ជ្រើសរើស "សួររកលេខកូដជានិច្ច" សម្រាប់កុំព្យូទ័ររួម ឬសាធារណៈ ដូចជា POS នៅក្នុងហាង។',
'Tfa_Guide_Trust_Note' => 'ការបន្ថយចំនួននេះនឹងកាត់បន្ថយរយៈពេលរបស់ឧបករណ៍ដែលបានទុកចិត្តរួចហើយ; ការបិទ 2FA ឬកំណត់វាឡើងវិញ នឹងបំភ្លេចពួកវាទាំងអស់។',
'Tfa_Guide_Lost_Title' => 'បាត់ទូរសព្ទ ហើយគ្មានលេខកូដសង្គ្រោះ',
'Tfa_Guide_Lost_Text' => 'នៅលើទំព័រអ្នកប្រើប្រាស់ អ្នកប្រើប្រាស់ដែលមាន 2FA បង្ហាញ "បើក" នៅក្នុងជួរឈរ 2FA។ ប៊ូតុងខែលនៅក្នុងសកម្មភាពនឹងកំណត់វាឡើងវិញ៖ អ្នកប្រើប្រាស់ចូលដោយប្រើតែពាក្យសម្ងាត់ ហើយរៀបចំកម្មវិធីម្តងទៀត (ឬត្រូវបានស្នើឱ្យធ្វើ ប្រសិនបើវាត្រូវបានតម្រូវ)។',
'Tfa_Guide_Lost_Warn' => 'បញ្ជាក់ថាអ្នកណាជាអ្នកស្នើសុំ មុនពេលកំណត់ឡើងវិញ — ការកំណត់ឡើងវិញនឹងដកការការពារដែល 2FA ផ្តល់ឱ្យគណនីនោះ។',
'Tfa_Guide_Open_Users' => 'បើកអ្នកប្រើប្រាស់',
'Tfa_Guide_Mobile_Title' => 'កម្មវិធីទូរសព្ទ និង API',
'Tfa_Guide_Mobile_Text' => 'កម្មវិធីទូរសព្ទ និងចំណុចបញ្ចប់ token របស់ API សួររកលេខកូដដូចគ្នា។ ប្រសិនបើ 2FA ត្រូវបានតម្រូវសម្រាប់អ្នកប្រើប្រាស់ដែលមិនទាន់បានរៀបចំវា ពួកគេត្រូវចូលនៅលើគេហទំព័រម្តងដើម្បីធ្វើដូច្នេះ។',
'Tfa_Guide_Protect_Title' => 'ការការពារដែលមានស្រាប់',
'Tfa_Guide_Protect_1' => 'លេខកូដខុស 5 ដង នឹងរារាំងការបញ្ចូលលេខកូដសម្រាប់អ្នកប្រើប្រាស់នោះរយៈពេល 15 នាទី ដោយមិនគិតពីការកំណត់ការចាក់សោខាងលើ។',
'Tfa_Guide_Protect_2' => 'លេខកូដនីមួយៗ និងលេខកូដសង្គ្រោះនីមួយៗប្រើបានតែម្តងប៉ុណ្ណោះ។',
'Tfa_Guide_Protect_3' => 'នៅពេលបើក "កត់ត្រាសកម្មភាពចូល" លេខកូដខុសនឹងបង្ហាញនៅក្នុងបញ្ជីសកម្មភាពចូលជា "លេខកូដ 2FA ខុស"។',
'Tfa_Guide_Trouble_Title' => 'ការដោះស្រាយបញ្ហា',
'Tfa_Guide_Faq_Clock_Q' => '“លេខកូដនោះមិនត្រឹមត្រូវទេ” ទោះប្រើលេខកូដថ្មី',
'Tfa_Guide_Faq_Clock_A' => 'នាឡិកាទូរសព្ទប្រហែលជាមិនត្រឹមត្រូវ។ លេខកូដពឹងផ្អែកលើពេលវេលា៖ កំណត់កាលបរិច្ឆេទ និងម៉ោងរបស់ទូរសព្ទឱ្យស្វ័យប្រវត្តិ (ម៉ោងបណ្តាញ) រួចសាកល្បងលេខកូដបន្ទាប់។',
'Tfa_Guide_Faq_Phone_Q' => 'ការផ្លាស់ទៅទូរសព្ទថ្មី',
'Tfa_Guide_Faq_Phone_A' => 'ប្រើមុខងារផ្ទេររបស់កម្មវិធីផ្ទៀងផ្ទាត់ខ្លួនឯង ឬបិទ 2FA នៅលើប្រវត្តិរូប ហើយបើកវាឡើងវិញជាមួយទូរសព្ទថ្មី (ប្រសិនបើវាត្រូវបានតម្រូវ សូមស្នើឱ្យអ្នកគ្រប់គ្រងកំណត់វាឡើងវិញជំនួសវិញ)។',
'Tfa_Guide_Faq_Locked_Q' => '“លេខកូដមិនត្រឹមត្រូវច្រើនពេក”',
'Tfa_Guide_Faq_Locked_A' => 'រង់ចាំរយៈពេលដែលបានបង្ហាញ (រហូតដល់ 15 នាទី) ឬឱ្យអ្នកគ្រប់គ្រងកំណត់ 2FA របស់អ្នកប្រើប្រាស់ឡើងវិញ។',
'Tfa_Guide_Faq_Key_Q' => 'គ្មាននរណាម្នាក់ដែលមាន 2FA អាចចូលបាន បន្ទាប់ពីផ្លាស់ប្តូរម៉ាស៊ីនមេ',
'Tfa_Guide_Faq_Key_A' => 'សម្ងាត់ 2FA ត្រូវបានអ៊ិនគ្រីបដោយ APP_KEY នៅក្នុងឯកសារ .env។ រក្សា APP_KEY ដដែលនៅពេលផ្លាស់ទី ឬស្តារកម្មវិធី; ប្រសិនបើវាបានផ្លាស់ប្តូរ អ្នកគ្រប់គ្រងដែលគ្មាន 2FA ត្រូវកំណត់អ្នកប្រើប្រាស់ដែលរងផលប៉ះពាល់ឡើងវិញ។',
'Tfa_Guide_Button' => 'មគ្គុទ្ទេសក៍',
'Tfa_Guide_Title' => 'មគ្គុទ្ទេសក៍ការផ្ទៀងផ្ទាត់ពីរកត្តា',
'Sec_2fa_Pending' => ':count នៅត្រូវរៀបចំ',
'Sec_2fa_See_Who' => 'មើលថាអ្នកណា',
'Sec_2fa_Grace_Off' => 'គ្មាន — រៀបចំនៅពេលចូលលើកក្រោយ',
'Sec_2fa_Applied' => 'អ្នកប្រើប្រាស់ :count នាក់ត្រូវបានចាកចេញ។',
'Tfa_Guide_Rollout_Title' => 'ដាក់ឱ្យប្រើសម្រាប់អ្នកប្រើប្រាស់គ្រប់រូប',
'Tfa_Guide_Rollout_1' => 'បើកវាសម្រាប់គណនីរបស់អ្នកជាមុនសិន (ប្រវត្តិរូប) ដើម្បីឱ្យអ្នកដឹងពីជំហាន។',
'Tfa_Guide_Rollout_2' => 'ប្រាប់ក្រុមរបស់អ្នកថាត្រូវដំឡើងកម្មវិធីណា ហើយការរៀបចំចំណាយពេលតែមួយនាទីនៅពេលចូល។',
'Tfa_Guide_Rollout_3' => 'បើក "តម្រូវឱ្យមានការផ្ទៀងផ្ទាត់ពីរកត្តា" ទុក "តម្រូវសម្រាប់" ឱ្យនៅទទេ (= អ្នកប្រើប្រាស់គ្រប់រូប) ហើយជ្រើសរើសរយៈពេលអនុគ្រោះតាមជម្រើស។ ចុច ដាក់ស្នើ។',
'Tfa_Guide_Rollout_4' => 'ចុច "ចាកចេញអ្នកប្រើប្រាស់ដែលគ្មាន 2FA" ដើម្បីឱ្យអ្នកដែលបានចូលរួចហើយរៀបចំវាឥឡូវនេះ ជំនួសឱ្យការរង់ចាំការចូលលើកក្រោយ។ អ្នកនៅតែស្ថិតក្នុងស្ថានភាពចូល។',
'Tfa_Guide_Rollout_5' => 'តាមដានវឌ្ឍនភាពជាមួយបញ្ជរនៅលើកាតនេះ ឬតម្រង "ត្រូវការរៀបចំ" នៅលើទំព័រអ្នកប្រើប្រាស់។',
'Tfa_Guide_Rollout_Note' => 'ជាមួយរយៈពេលអនុគ្រោះ អេក្រង់រៀបចំបង្ហាញ “រំលឹកខ្ញុំពេលក្រោយ” រហូតដល់ថ្ងៃផុតកំណត់; បន្ទាប់ពីនោះ ការរៀបចំគឺតម្រូវដើម្បីចូល។',
'Tfa_Guide_Customers_Title' => 'គណនីអតិថិជន (ហាង និងវិបផតថលអតិថិជន)',
'Tfa_Guide_Customers_Text' => 'អតិថិជនក៏អាចការពារគណនីរបស់ខ្លួនបានដែរ។ វាជាជម្រើសសម្រាប់អតិថិជនម្នាក់ៗ ហើយមិនដែលបង្ខំទេ៖ បើកវានៅក្រោម ការកំណត់ហាង → ការគ្រប់គ្រងសិទ្ធិចុះឈ្មោះ (ហាងអនឡាញ) និង វិបផតថលអតិថិជន → ការកំណត់វិបផតថល (វិបផតថលអតិថិជន)។',
'Tfa_Guide_Customers_1' => 'អតិថិជនបើកវាពី គណនីរបស់ខ្ញុំ (ហាង) ឬ ប្រវត្តិរូប (វិបផតថល)។',
'Tfa_Guide_Customers_2' => 'ពួកគេជ្រើសរើសលេខកូដដែលផ្ញើតាមអ៊ីមែល — ងាយស្រួលបំផុត មិនត្រូវការកម្មវិធី — ឬកម្មវិធីផ្ទៀងផ្ទាត់ជាមួយលេខកូដសង្គ្រោះ។',
'Tfa_Guide_Customers_3' => 'លេខកូដតាមអ៊ីមែលត្រូវការការកំណត់សំបុត្រដែលដំណើរការ (ការកំណត់ → ការកំណត់សំបុត្រ)។ ពួកវាផុតកំណត់បន្ទាប់ពី 10 នាទី។',
'Tfa_Guide_Customers_4' => 'ការបិទជម្រើសនេះនៅពេលក្រោយនឹងបញ្ឈប់ការរៀបចំថ្មី; អតិថិជនដែលកំពុងប្រើវារួចហើយនៅតែត្រូវបានសួរ ហើយអាចបិទវាដោយខ្លួនឯង។',
'Tfa_Required_Grace_Notice' => 'អ្នកគ្រប់គ្រងរបស់អ្នកតម្រូវឱ្យមានការផ្ទៀងផ្ទាត់ពីរកត្តា។ អ្នកអាចពន្យារវានៅពេលចូលរហូតដល់ :date; បន្ទាប់ពីនោះ ការរៀបចំគឺតម្រូវ។',
'Tfa_Filter_All' => '2FA៖ អ្នកប្រើប្រាស់ទាំងអស់',
